package game

import (
	"os"
	"strings"

	"oldworld2/internal/assets"
	"oldworld2/internal/gfx"
	"oldworld2/internal/procgen"
)

// Comic art generated by tools/artgen into assets/generated/: battle backgrounds per zone
// type. Every image is optional: without it the battle uses a plain backdrop.

const battleArtDir = "generated/battle"

func battleBackgroundID(z procgen.ZoneType) string {
	return "bg_" + strings.ReplaceAll(strings.ToLower(z.String()), " ", "_")
}

// battleArt returns a comic battle image by ID, or nil if it doesn't exist.
func (g *Game) battleArt(id string) *gfx.Image { return g.art(battleArtDir + "/" + id) }

// art returns a comic image by its path under the assets directory without ".png", or nil if
// it doesn't exist. Images are loaded once.
func (g *Game) art(rel string) *gfx.Image {
	if img, ok := g.comic[rel]; ok {
		return img
	}
	var img *gfx.Image
	path := rel + ".png"
	if _, err := os.Stat(assets.Path(g.opts.AssetsDir, path)); err == nil {
		if src, err := assets.LoadImage(g.opts.AssetsDir, path); err == nil {
			img = gfx.NewImageFromImage(src)
		}
	}
	if g.comic == nil {
		g.comic = map[string]*gfx.Image{}
	}
	g.comic[rel] = img
	return img
}
